"""p229: first join to a brand-new 1.20.4 world (generated by the dedicated server), under JFR.

No synthetic clicks: generate the world headlessly, copy it into the client saves, quickplay in.
"""
from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import time
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
RUN = Path(__file__).resolve().parent
GAME = ROOT / "work" / "launcher-e2e"
WORK = ROOT / "work" / "tmp" / "p229-server"
JFR = Path(r"D:\mcbridge-data\work\tmp\p229.jfr")
JCMD = Path(r"C:\Users\27682\Documents\新建文件夹\.toolchain\jdk\bin\jcmd.exe")
JAVA = Path(r"C:\Users\27682\Documents\新建文件夹\.toolchain\jdk\bin\java.exe")
sys.path.insert(0, str(ROOT / "launcher"))
sys.path.insert(0, str(ROOT / "tools"))
import mclaunch  # noqa: E402
import from_source_install as fs  # noqa: E402


def main() -> int:
    WORK.mkdir(parents=True, exist_ok=True)
    server_jar = WORK / "server.jar"
    if not server_jar.exists() or server_jar.stat().st_size < 10_000_000:
        man = fs.get_json(fs.MANIFEST)
        entry = next(v for v in man["versions"] if v["id"] == "1.20.4")
        vjson = fs.get_json(entry["url"])
        url = vjson["downloads"]["server"]["url"]
        print("server url", url, flush=True)
        data = fs.http_get(url, timeout=180)
        server_jar.write_bytes(data)
    print("server.jar", server_jar.stat().st_size, flush=True)

    (WORK / "eula.txt").write_text("eula=true\n", encoding="utf-8")
    (WORK / "server.properties").write_text(
        "level-name=p229world\nlevel-seed=1201\nonline-mode=false\nview-distance=4\n"
        "simulation-distance=4\nspawn-protection=0\nenable-command-block=false\n",
        encoding="utf-8")
    srv = subprocess.Popen([str(JAVA), "-Xmx1G", "-jar", "server.jar", "nogui"],
                           cwd=str(WORK), stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                           stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace")
    done = False
    start = time.time()
    assert srv.stdout is not None
    for line in srv.stdout:
        if "Done (" in line or "For help, type" in line:
            done = True
            break
        if time.time() - start > 240:
            break
    print("server done:", done, flush=True)
    try:
        srv.stdin.write("stop\n")
        srv.stdin.flush()
    except Exception:
        pass
    try:
        srv.wait(timeout=120)
    except subprocess.TimeoutExpired:
        srv.kill()

    world = WORK / "p229world"
    if not (world / "level.dat").exists():
        print("no world generated")
        return 2
    dst = GAME / "saves" / "p229-world"
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(world, dst)
    print("world copied ->", dst, flush=True)

    JFR.unlink(missing_ok=True)
    agent = Path(os.environ.get("P229_AGENT",
                                str(ROOT / "runs" / "p230-not-a-string-agent" / "trace-agent.jar")))
    extra_jvm = [f"-XX:StartFlightRecording=filename={JFR},settings=profile,dumponexit=true"]
    if agent.exists():
        extra_jvm.append(f"-javaagent:{agent}")
        print("agent:", agent, flush=True)
    cmd, log, _ = mclaunch.build_command(
        "1.20.4", GAME, "SelYio", "2G",
        extra_jvm=extra_jvm,
        extra_game=["--quickPlaySingleplayer", "p229-world"])
    for i, a in enumerate(cmd):
        if a in ("--uuid", "--accessToken") and i + 1 < len(cmd):
            cmd[i + 1] = "00000000-0000-3006-998f-555b73d6dcef"
    log.parent.mkdir(parents=True, exist_ok=True)
    out = open(log, "w", encoding="utf-8", errors="replace")
    proc = subprocess.Popen(cmd, cwd=str(GAME), stdout=out, stderr=subprocess.STDOUT)
    print("client pid", proc.pid, flush=True)
    latest = GAME / "logs" / "latest.log"
    latest.unlink(missing_ok=True)
    seen = False
    try:
        for _ in range(90):
            time.sleep(2)
            text = latest.read_text(encoding="utf-8", errors="replace") if latest.exists() else ""
            if "Not a string" in text:
                seen = True
                print("MARKER: Not a string seen", flush=True)
                break
            if "joined the game" in text:
                print("joined; waiting 8s", flush=True)
                time.sleep(8)
                break
            if proc.poll() is not None:
                break
        text = latest.read_text(encoding="utf-8", errors="replace") if latest.exists() else ""
        result = {"joined": "joined the game" in text, "not_a_string": "Not a string" in text,
                  "server_done": done}
    finally:
        if proc.poll() is None:
            time.sleep(3)
            for attempt in range(3):
                r = subprocess.run([str(JCMD), str(proc.pid), "JFR.dump", f"filename={JFR}"],
                                   capture_output=True, text=True, encoding="utf-8", errors="replace")
                time.sleep(2)
                size = JFR.stat().st_size if JFR.exists() else 0
                print("jfr dump", attempt, r.returncode, size, flush=True)
                if size > 100_000:
                    break
            r = subprocess.run([str(JCMD), str(proc.pid), "JFR.stop"],
                               capture_output=True, text=True, encoding="utf-8", errors="replace")
            print("jfr stop", r.returncode, flush=True)
            time.sleep(1)
            proc.terminate()
            try:
                proc.wait(timeout=8)
            except subprocess.TimeoutExpired:
                proc.kill()
        out.close()
    (RUN / "result.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps(result, ensure_ascii=False), flush=True)
    return 0 if result["not_a_string"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
